//! MSVC mangling corpus — golden symbols generated by
//! `clang -target x86_64-pc-windows-msvc -fms-compatibility` against
//! the .cpp sources in `tests/corpus_msvc/`, plus per-symbol diff tests
//! that exercise `ctx.mangle_msvc()` against the same goldens.
//!
//! The goldens are checked in (not regenerated at test time) so the
//! suite runs without a network or a working cross-target clang. To
//! refresh after editing the .cpp files, run
//! `fork/tests/refresh-msvc-corpus.sh` from the rustcc tree.

use std::collections::HashSet;
use std::path::PathBuf;

use rustc_abi_cxx::{
    Access, BaseSpec, ClassDef, ClassId, CtorVariant, CvQual, CxxType,
    CxxTypeCtx, DtorVariant, FloatKind, FnSig, Ident, IntWidth, MethodName,
    NameSegment, NestedName, OperatorKind, RecordKind, RefKind, Symbol,
    TemplateArg, Target, TypeId, Virtuality,
};
use test_support::golden::{self, MangleDump};

fn corpus_path(filename: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/corpus_msvc")
        .join(filename)
}

fn load(basename: &str) -> MangleDump {
    let path = corpus_path(&format!("{basename}.mangle.golden"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "failed to read {} ({e}). Run \
             fork/tests/refresh-msvc-corpus.sh.",
            path.display()
        )
    });
    golden::parse_mangle(&text).unwrap_or_else(|e| {
        panic!("failed to parse {}: {e}", path.display())
    })
}

fn ctx() -> CxxTypeCtx {
    CxxTypeCtx::new(Target::x86_64_pc_windows_msvc())
}

fn intern_int(ctx: &mut CxxTypeCtx, signed: bool, width: IntWidth) -> TypeId {
    ctx.intern_type(CxxType::Int { signed, width })
}

fn intern_void(ctx: &mut CxxTypeCtx) -> TypeId {
    ctx.intern_type(CxxType::Void)
}

fn intern_float(ctx: &mut CxxTypeCtx, kind: FloatKind) -> TypeId {
    ctx.intern_type(CxxType::Float { kind })
}

fn assert_all_msvc(dump: &MangleDump, expected: &[(&str, &str)]) {
    let set: HashSet<&str> = dump.symbols.iter().map(String::as_str).collect();
    let missing: Vec<_> = expected
        .iter()
        .filter(|(_, m)| !set.contains(*m))
        .collect();
    assert!(
        missing.is_empty(),
        "expected MSVC symbols missing from golden — clang's output may \
         have changed, or the .cpp no longer defines them: {missing:?}"
    );
}

// -------- mangle_basic --------------------------------------------------

const BASIC_EXPECTED: &[(&str, &str)] = &[
    ("Foo::Foo()", "??0Foo@@QEAA@XZ"),
    ("Foo::Foo(int)", "??0Foo@@QEAA@H@Z"),
    ("Foo::~Foo()", "??1Foo@@QEAA@XZ"),
    ("Foo::bar(int)", "?bar@Foo@@QEAAXH@Z"),
    ("Foo::bar(double) const", "?bar@Foo@@QEBAXN@Z"),
    ("free_fn(int)", "?free_fn@@YAXH@Z"),
];

#[test]
fn msvc_basic_golden_has_expected_symbols() {
    let d = load("mangle_basic");
    assert_all_msvc(&d, BASIC_EXPECTED);
    for s in &d.symbols {
        assert!(
            s.starts_with('?'),
            "MSVC mangled symbol should start with '?': {s}"
        );
    }
}

#[test]
fn msvc_basic_matches_clang() {
    let mut c = ctx();
    let i = intern_int(&mut c, true, IntWidth::I32);
    let v = intern_void(&mut c);
    let d = intern_float(&mut c, FloatKind::F64);
    let foo = c.define_class(ClassDef {
        name: NestedName(vec![NameSegment::Class(Ident("Foo".into()))]),
        bases: vec![],
        fields: vec![],
        methods: vec![],
        kind: RecordKind::Struct,
        is_polymorphic: false,
        is_final: false,
        source_alignment: None,
    });

    // free_fn(int)
    let sig = FnSig {
        params: vec![i],
        ret: v,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Function {
            scope: NestedName(vec![]),
            name: Ident("free_fn".into()),
            sig: sig.clone(),
        }),
        "?free_fn@@YAXH@Z"
    );

    // Foo::Foo()
    let ctor_sig0 = FnSig {
        params: vec![],
        ret: v,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Ctor {
            class: foo,
            variant: CtorVariant::C1,
            sig: ctor_sig0,
        }),
        "??0Foo@@QEAA@XZ"
    );

    // Foo::Foo(int)
    let ctor_sig1 = FnSig {
        params: vec![i],
        ret: v,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Ctor {
            class: foo,
            variant: CtorVariant::C1,
            sig: ctor_sig1,
        }),
        "??0Foo@@QEAA@H@Z"
    );

    // Foo::~Foo()
    assert_eq!(
        c.mangle_msvc(&Symbol::Dtor {
            class: foo,
            variant: DtorVariant::D1,
        }),
        "??1Foo@@QEAA@XZ"
    );

    // Foo::bar(int)
    let bar_int_sig = FnSig {
        params: vec![i],
        ret: v,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: foo,
            name: MethodName::Ident(Ident("bar".into())),
            sig: bar_int_sig,
        }),
        "?bar@Foo@@QEAAXH@Z"
    );

    // Foo::bar(double) const
    let bar_d_sig = FnSig {
        params: vec![d],
        ret: v,
        cv: CvQual { is_const: true, is_volatile: false },
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: foo,
            name: MethodName::Ident(Ident("bar".into())),
            sig: bar_d_sig,
        }),
        "?bar@Foo@@QEBAXN@Z"
    );
}

