#[test]
fn msvc_types_matches_clang() {
    let mut c = ctx();
    let v = intern_void(&mut c);

    fn free_void_taking(
        c: &mut CxxTypeCtx,
        name: &str,
        param: TypeId,
        ret: TypeId,
    ) -> String {
        let sig = FnSig {
            params: vec![param],
            ret,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        };
        c.mangle_msvc(&Symbol::Function {
            scope: NestedName(vec![]),
            name: Ident(name.into()),
            sig,
        })
    }

    // Builtin types
    let cases = [
        ("t_bool", CxxType::Bool, "?t_bool@@YAX_N@Z"),
        (
            "t_int8",
            CxxType::Int { signed: true, width: IntWidth::I8 },
            "?t_int8@@YAXD@Z",
        ),
        (
            "t_uint8",
            CxxType::Int { signed: false, width: IntWidth::I8 },
            "?t_uint8@@YAXE@Z",
        ),
        (
            "t_int16",
            CxxType::Int { signed: true, width: IntWidth::I16 },
            "?t_int16@@YAXF@Z",
        ),
        (
            "t_uint16",
            CxxType::Int { signed: false, width: IntWidth::I16 },
            "?t_uint16@@YAXG@Z",
        ),
        (
            "t_int32",
            CxxType::Int { signed: true, width: IntWidth::I32 },
            "?t_int32@@YAXH@Z",
        ),
        (
            "t_uint32",
            CxxType::Int { signed: false, width: IntWidth::I32 },
            "?t_uint32@@YAXI@Z",
        ),
        (
            "t_int64",
            CxxType::Int { signed: true, width: IntWidth::I64 },
            "?t_int64@@YAX_J@Z",
        ),
        (
            "t_uint64",
            CxxType::Int { signed: false, width: IntWidth::I64 },
            "?t_uint64@@YAX_K@Z",
        ),
        (
            "t_f32",
            CxxType::Float { kind: FloatKind::F32 },
            "?t_f32@@YAXM@Z",
        ),
        (
            "t_f64",
            CxxType::Float { kind: FloatKind::F64 },
            "?t_f64@@YAXN@Z",
        ),
    ];
    for (name, ty, expected) in cases {
        let id = c.intern_type(ty);
        let got = free_void_taking(&mut c, name, id, v);
        assert_eq!(
            got, expected,
            "mangling of {name}: got {got}, expected {expected}"
        );
    }

    // t_void() - special case (no params)
    let void_sig = FnSig {
        params: vec![],
        ret: v,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Function {
            scope: NestedName(vec![]),
            name: Ident("t_void".into()),
            sig: void_sig,
        }),
        "?t_void@@YAXXZ"
    );

    // Pointer variants
    let i = intern_int(&mut c, true, IntWidth::I32);
    let p = c.intern_type(CxxType::Ptr { pointee: i, cv: CvQual::default() });
    let pc = c.intern_type(CxxType::Ptr {
        pointee: i,
        cv: CvQual { is_const: true, is_volatile: false },
    });
    let pv = c.intern_type(CxxType::Ptr {
        pointee: i,
        cv: CvQual { is_const: false, is_volatile: true },
    });
    let pcv = c.intern_type(CxxType::Ptr {
        pointee: i,
        cv: CvQual { is_const: true, is_volatile: true },
    });
    let pp = c.intern_type(CxxType::Ptr { pointee: p, cv: CvQual::default() });
    let r = c.intern_type(CxxType::Ref {
        pointee: i,
        kind: RefKind::Lvalue,
        cv: CvQual::default(),
    });
    let rc = c.intern_type(CxxType::Ref {
        pointee: i,
        kind: RefKind::Lvalue,
        cv: CvQual { is_const: true, is_volatile: false },
    });

    let ptr_cases = [
        ("p_int", p, "?p_int@@YAXPEAH@Z"),
        ("p_const_int", pc, "?p_const_int@@YAXPEBH@Z"),
        ("p_volatile_int", pv, "?p_volatile_int@@YAXPECH@Z"),
        ("p_const_volatile_int", pcv, "?p_const_volatile_int@@YAXPEDH@Z"),
        ("p_p_int", pp, "?p_p_int@@YAXPEAPEAH@Z"),
        ("r_int", r, "?r_int@@YAXAEAH@Z"),
        ("r_const_int", rc, "?r_const_int@@YAXAEBH@Z"),
    ];
    for (name, ty, expected) in ptr_cases {
        let got = free_void_taking(&mut c, name, ty, v);
        assert_eq!(
            got, expected,
            "mangling of {name}: got {got}, expected {expected}"
        );
    }
}

