#[test]
fn msvc_nested_matches_clang() {
    let mut c = ctx();
    let i = intern_int(&mut c, true, IntWidth::I32);
    // namespace N { namespace M { struct S { int x; }; ... } }
    let s = c.define_class(ClassDef {
        name: NestedName(vec![
            NameSegment::Namespace(Ident("N".into())),
            NameSegment::Namespace(Ident("M".into())),
            NameSegment::Class(Ident("S".into())),
        ]),
        bases: vec![],
        fields: vec![],
        methods: vec![],
        kind: RecordKind::Struct,
        is_polymorphic: false,
        is_final: false,
        source_alignment: None,
    });
    let s_ty = c.intern_type(CxxType::Record(s));

    // N::M::f(N::M::S) -> ?f@M@N@@YAHUS@12@@Z
    let f_sig = FnSig {
        params: vec![s_ty],
        ret: i,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    let f_mangled = c.mangle_msvc(&Symbol::Function {
        scope: NestedName(vec![
            NameSegment::Namespace(Ident("N".into())),
            NameSegment::Namespace(Ident("M".into())),
        ]),
        name: Ident("f".into()),
        sig: f_sig,
    });
    assert_eq!(f_mangled, "?f@M@N@@YAHUS@12@@Z");

    // N::g(N::M::S) -> ?g@N@@YAHUS@M@1@@Z
    let mut c2 = ctx();
    let i2 = intern_int(&mut c2, true, IntWidth::I32);
    let s2 = c2.define_class(ClassDef {
        name: NestedName(vec![
            NameSegment::Namespace(Ident("N".into())),
            NameSegment::Namespace(Ident("M".into())),
            NameSegment::Class(Ident("S".into())),
        ]),
        bases: vec![],
        fields: vec![],
        methods: vec![],
        kind: RecordKind::Struct,
        is_polymorphic: false,
        is_final: false,
        source_alignment: None,
    });
    let s2_ty = c2.intern_type(CxxType::Record(s2));
    let g_sig = FnSig {
        params: vec![s2_ty],
        ret: i2,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    let g_mangled = c2.mangle_msvc(&Symbol::Function {
        scope: NestedName(vec![NameSegment::Namespace(Ident("N".into()))]),
        name: Ident("g".into()),
        sig: g_sig,
    });
    assert_eq!(g_mangled, "?g@N@@YAHUS@M@1@@Z");
}

