const OPERATORS_EXPECTED: &[(&str, &str)] = &[
    // ??4 = operator=. Returns Vec& (lvalue ref), takes const Vec&.
    ("Vec::operator=", "??4Vec@@QEAAAEAU0@AEBU0@@Z"),
    // ??8 = operator== const. Returns bool, takes const Vec&.
    ("Vec::operator==", "??8Vec@@QEBA_NAEBU0@@Z"),
    // ??A = operator[]. Returns int, takes int.
    ("Vec::operator[]", "??AVec@@QEAAHH@Z"),
    // ??H = operator+ const. Returns Vec by value (?A prefix),
    // takes const Vec&.
    ("Vec::operator+", "??HVec@@QEBA?AU0@AEBU0@@Z"),
    // ??M = operator< const. Returns bool, takes const Vec&.
    ("Vec::operator<", "??MVec@@QEBA_NAEBU0@@Z"),
];

#[test]
fn msvc_operators_golden_has_expected_symbols() {
    let d = load("mangle_operators");
    assert_all_msvc(&d, OPERATORS_EXPECTED);
}

#[test]
fn msvc_operators_matches_clang() {
    let mut c = ctx();
    let i = intern_int(&mut c, true, IntWidth::I32);
    let b = c.intern_type(CxxType::Bool);
    let vec = c.define_class(ClassDef {
        name: NestedName(vec![NameSegment::Class(Ident("Vec".into()))]),
        bases: vec![],
        fields: vec![],
        methods: vec![],
        kind: RecordKind::Struct,
        is_polymorphic: false,
        is_final: false,
        source_alignment: None,
    });
    let vec_ty = c.intern_type(CxxType::Record(vec));
    let vec_ref = c.intern_type(CxxType::Ref {
        pointee: vec_ty,
        kind: RefKind::Lvalue,
        cv: CvQual::default(),
    });
    let vec_cref = c.intern_type(CxxType::Ref {
        pointee: vec_ty,
        kind: RefKind::Lvalue,
        cv: CvQual { is_const: true, is_volatile: false },
    });

    // Vec::operator+(const Vec&) const -> ??HVec@@QEBA?AU0@AEBU0@@Z
    let plus_sig = FnSig {
        params: vec![vec_cref],
        ret: vec_ty,
        cv: CvQual { is_const: true, is_volatile: false },
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: vec,
            name: MethodName::Operator(OperatorKind::Plus),
            sig: plus_sig,
        }),
        "??HVec@@QEBA?AU0@AEBU0@@Z"
    );

    // Vec::operator=(const Vec&) -> ??4Vec@@QEAAAEAU0@AEBU0@@Z
    let assign_sig = FnSig {
        params: vec![vec_cref],
        ret: vec_ref,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: vec,
            name: MethodName::Operator(OperatorKind::Assign),
            sig: assign_sig,
        }),
        "??4Vec@@QEAAAEAU0@AEBU0@@Z"
    );

    // Vec::operator[](int) -> ??AVec@@QEAAHH@Z
    let index_sig = FnSig {
        params: vec![i],
        ret: i,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: vec,
            name: MethodName::Operator(OperatorKind::Index),
            sig: index_sig,
        }),
        "??AVec@@QEAAHH@Z"
    );

    // Vec::operator==(const Vec&) const -> ??8Vec@@QEBA_NAEBU0@@Z
    let eq_sig = FnSig {
        params: vec![vec_cref],
        ret: b,
        cv: CvQual { is_const: true, is_volatile: false },
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: vec,
            name: MethodName::Operator(OperatorKind::Eq),
            sig: eq_sig,
        }),
        "??8Vec@@QEBA_NAEBU0@@Z"
    );

    // Vec::operator<(const Vec&) const -> ??MVec@@QEBA_NAEBU0@@Z
    let lt_sig = FnSig {
        params: vec![vec_cref],
        ret: b,
        cv: CvQual { is_const: true, is_volatile: false },
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: vec,
            name: MethodName::Operator(OperatorKind::Lt),
            sig: lt_sig,
        }),
        "??MVec@@QEBA_NAEBU0@@Z"
    );
}

