const INHERIT_EXPECTED: &[(&str, &str)] = &[
    ("Base::f(int) [virtual]", "?f@Base@@UEAAXH@Z"),
    ("Base::g() const [virtual]", "?g@Base@@UEBAHXZ"),
    ("Base::~Base() [virtual]", "??1Base@@UEAA@XZ"),
    ("Derived::f(int) [override]", "?f@Derived@@UEAAXH@Z"),
    ("Derived::g() const [override]", "?g@Derived@@UEBAHXZ"),
    ("Derived::~Derived() [virtual]", "??1Derived@@UEAA@XZ"),
];

#[test]
fn msvc_inherit_golden_has_expected_symbols() {
    let d = load("mangle_inherit");
    assert_all_msvc(&d, INHERIT_EXPECTED);
}

#[test]
fn msvc_inherit_matches_clang_virtual_access_letter() {
    let mut c = ctx();
    let v = intern_void(&mut c);
    let i = intern_int(&mut c, true, IntWidth::I32);

    // struct Base { virtual void f(int); virtual int g() const; virtual ~Base(); };
    let f_method = rustc_abi_cxx::MethodDef {
        name: MethodName::Ident(Ident("f".into())),
        sig: FnSig {
            params: vec![i],
            ret: v,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        },
        virtuality: Virtuality::Virtual,
        vtable_index: None,
        special: None,
    };
    let g_method = rustc_abi_cxx::MethodDef {
        name: MethodName::Ident(Ident("g".into())),
        sig: FnSig {
            params: vec![],
            ret: i,
            cv: CvQual { is_const: true, is_volatile: false },
            ref_q: None,
            variadic: false,
            noexcept: false,
        },
        virtuality: Virtuality::Virtual,
        vtable_index: None,
        special: None,
    };
    let dtor_method = rustc_abi_cxx::MethodDef {
        name: MethodName::Ident(Ident("~Base".into())),
        sig: FnSig {
            params: vec![],
            ret: v,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        },
        virtuality: Virtuality::Virtual,
        vtable_index: None,
        special: Some(rustc_abi_cxx::SpecialMember::Dtor),
    };
    let base = c.define_class(ClassDef {
        name: NestedName(vec![NameSegment::Class(Ident("Base".into()))]),
        bases: vec![],
        fields: vec![],
        methods: vec![f_method.clone(), g_method.clone(), dtor_method.clone()],
        kind: RecordKind::Struct,
        is_polymorphic: true,
        is_final: false,
        source_alignment: None,
    });

    // Base::f(int) - virtual -> ?f@Base@@UEAAXH@Z
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: base,
            name: MethodName::Ident(Ident("f".into())),
            sig: f_method.sig.clone(),
        }),
        "?f@Base@@UEAAXH@Z"
    );

    // Base::g() const - virtual -> ?g@Base@@UEBAHXZ
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: base,
            name: MethodName::Ident(Ident("g".into())),
            sig: g_method.sig.clone(),
        }),
        "?g@Base@@UEBAHXZ"
    );

    // Base::~Base() - virtual -> ??1Base@@UEAA@XZ
    assert_eq!(
        c.mangle_msvc(&Symbol::Dtor {
            class: base,
            variant: DtorVariant::D1,
        }),
        "??1Base@@UEAA@XZ"
    );

    // struct Derived : Base — its dtor is implicitly virtual.
    let dtor_d = rustc_abi_cxx::MethodDef {
        name: MethodName::Ident(Ident("~Derived".into())),
        sig: FnSig {
            params: vec![],
            ret: v,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        },
        virtuality: Virtuality::Virtual,
        vtable_index: None,
        special: Some(rustc_abi_cxx::SpecialMember::Dtor),
    };
    let derived = c.define_class(ClassDef {
        name: NestedName(vec![NameSegment::Class(Ident("Derived".into()))]),
        bases: vec![rustc_abi_cxx::BaseSpec {
            class: base,
            virtual_: false,
            access: rustc_abi_cxx::Access::Public,
        }],
        fields: vec![],
        methods: vec![f_method.clone(), g_method.clone(), dtor_d],
        kind: RecordKind::Struct,
        is_polymorphic: true,
        is_final: false,
        source_alignment: None,
    });

    // Derived::f(int) - virtual override -> ?f@Derived@@UEAAXH@Z
    assert_eq!(
        c.mangle_msvc(&Symbol::Method {
            class: derived,
            name: MethodName::Ident(Ident("f".into())),
            sig: f_method.sig.clone(),
        }),
        "?f@Derived@@UEAAXH@Z"
    );

    // Derived::~Derived() -> ??1Derived@@UEAA@XZ
    assert_eq!(
        c.mangle_msvc(&Symbol::Dtor {
            class: derived,
            variant: DtorVariant::D1,
        }),
        "??1Derived@@UEAA@XZ"
    );
}

// -------- mangle_substitutions (type + name back-refs) ---------------

const SUBS_EXPECTED: &[(&str, &str)] = &[
    // Two by-value V — top-level type back-ref fires.
    ("g_vv(V, V)", "?g_vv@@YAXUV@@0@Z"),
    // V then V& — different top-level types. Inner V name back-refs.
    ("g_vr(V, V&)", "?g_vr@@YAXUV@@AEAU1@@Z"),
    // Two V* — top-level type back-ref.
    ("g_pp(V*, V*)", "?g_pp@@YAXPEAUV@@0@Z"),
    // V*, V&, V — three different top-level types. Name back-refs
    // throughout.
    ("g_pvr(V*, V&, V)", "?g_pvr@@YAXPEAUV@@AEAU1@U1@@Z"),
    // int* repeated — top-level type back-ref on builtins-via-ptr.
    ("g_ipp(int*, int*)", "?g_ipp@@YAXPEAH0@Z"),
    ("g_ippp(int*, int*, int*)", "?g_ippp@@YAXPEAH00@Z"),
];

#[test]
fn msvc_substitutions_golden_has_expected_symbols() {
    let d = load("mangle_substitutions");
    assert_all_msvc(&d, SUBS_EXPECTED);
}

#[test]
fn msvc_substitutions_matches_clang() {
    fn ctx_with_v() -> (CxxTypeCtx, ClassId, TypeId, TypeId, TypeId, TypeId) {
        let mut c = ctx();
        let i = intern_int(&mut c, true, IntWidth::I32);
        let v_class = c.define_class(ClassDef {
            name: NestedName(vec![NameSegment::Class(Ident("V".into()))]),
            bases: vec![],
            fields: vec![],
            methods: vec![],
            kind: RecordKind::Struct,
            is_polymorphic: false,
            is_final: false,
            source_alignment: None,
        });
        let v_ty = c.intern_type(CxxType::Record(v_class));
        let v_ptr = c.intern_type(CxxType::Ptr { pointee: v_ty, cv: CvQual::default() });
        let v_ref = c.intern_type(CxxType::Ref {
            pointee: v_ty,
            kind: RefKind::Lvalue,
            cv: CvQual::default(),
        });
        (c, v_class, i, v_ty, v_ptr, v_ref)
    }

    fn mangle_free(c: &mut CxxTypeCtx, name: &str, params: Vec<TypeId>, ret: TypeId) -> String {
        let sig = FnSig {
            params,
            ret,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        };
        c.mangle_msvc(&Symbol::Function {
            scope: NestedName(vec![]),
            name: Ident(name.into()),
            sig,
        })
    }

    // g_vv(V, V) → ?g_vv@@YAXUV@@0@Z
    {
        let (mut c, _, _, v_ty, _, _) = ctx_with_v();
        let v = intern_void(&mut c);
        assert_eq!(
            mangle_free(&mut c, "g_vv", vec![v_ty, v_ty], v),
            "?g_vv@@YAXUV@@0@Z"
        );
    }

    // g_vr(V, V&) → ?g_vr@@YAXUV@@AEAU1@@Z
    {
        let (mut c, _, _, v_ty, _, v_ref) = ctx_with_v();
        let v = intern_void(&mut c);
        assert_eq!(
            mangle_free(&mut c, "g_vr", vec![v_ty, v_ref], v),
            "?g_vr@@YAXUV@@AEAU1@@Z"
        );
    }

    // g_pp(V*, V*) → ?g_pp@@YAXPEAUV@@0@Z
    {
        let (mut c, _, _, _, v_ptr, _) = ctx_with_v();
        let v = intern_void(&mut c);
        assert_eq!(
            mangle_free(&mut c, "g_pp", vec![v_ptr, v_ptr], v),
            "?g_pp@@YAXPEAUV@@0@Z"
        );
    }

    // g_pvr(V*, V&, V) → ?g_pvr@@YAXPEAUV@@AEAU1@U1@@Z
    {
        let (mut c, _, _, v_ty, v_ptr, v_ref) = ctx_with_v();
        let v = intern_void(&mut c);
        assert_eq!(
            mangle_free(&mut c, "g_pvr", vec![v_ptr, v_ref, v_ty], v),
            "?g_pvr@@YAXPEAUV@@AEAU1@U1@@Z"
        );
    }

    // g_ipp(int*, int*) → ?g_ipp@@YAXPEAH0@Z
    {
        let mut c = ctx();
        let v = intern_void(&mut c);
        let i = intern_int(&mut c, true, IntWidth::I32);
        let ip = c.intern_type(CxxType::Ptr { pointee: i, cv: CvQual::default() });
        assert_eq!(
            mangle_free(&mut c, "g_ipp", vec![ip, ip], v),
            "?g_ipp@@YAXPEAH0@Z"
        );
    }

    // g_ippp(int*, int*, int*) → ?g_ippp@@YAXPEAH00@Z
    {
        let mut c = ctx();
        let v = intern_void(&mut c);
        let i = intern_int(&mut c, true, IntWidth::I32);
        let ip = c.intern_type(CxxType::Ptr { pointee: i, cv: CvQual::default() });
        assert_eq!(
            mangle_free(&mut c, "g_ippp", vec![ip, ip, ip], v),
            "?g_ippp@@YAXPEAH00@Z"
        );
    }
}

// -------- mangle_templates (class-template specializations) ----------

const TEMPLATES_EXPECTED: &[(&str, &str)] = &[
    // take_int_box(Box<int>) → `U?$Box@H@@`
    ("take_int_box(Box<int>)", "?take_int_box@@YAXU?$Box@H@@@Z"),
    // take_two(Box<int>, Box<int>) — second is type back-ref `0`.
    ("take_two(Box<int>, Box<int>)", "?take_two@@YAXU?$Box@H@@0@Z"),
    // take_int_and_float — different instantiations, no compression.
    (
        "take_int_and_float(Box<int>, Box<float>)",
        "?take_int_and_float@@YAXU?$Box@H@@U?$Box@M@@@Z",
    ),
];

#[test]
fn msvc_templates_golden_has_expected_symbols() {
    let d = load("mangle_templates");
    assert_all_msvc(&d, TEMPLATES_EXPECTED);
}

#[test]
fn msvc_templates_matches_clang() {
    fn make_ctx() -> (CxxTypeCtx, TypeId, TypeId, TypeId, TypeId) {
        let mut c = ctx();
        let v = intern_void(&mut c);
        let i = intern_int(&mut c, true, IntWidth::I32);
        let f = intern_float(&mut c, FloatKind::F32);
        // Two ClassDefs: Box<int> and Box<float>. Each carries the
        // TemplateSpec segment as its NestedName.
        let box_int = c.define_class(ClassDef {
            name: NestedName(vec![NameSegment::TemplateSpec {
                name: Ident("Box".into()),
                args: vec![TemplateArg::Type(i)],
            }]),
            bases: vec![],
            fields: vec![],
            methods: vec![],
            kind: RecordKind::Struct,
            is_polymorphic: false,
            is_final: false,
            source_alignment: None,
        });
        let box_float = c.define_class(ClassDef {
            name: NestedName(vec![NameSegment::TemplateSpec {
                name: Ident("Box".into()),
                args: vec![TemplateArg::Type(f)],
            }]),
            bases: vec![],
            fields: vec![],
            methods: vec![],
            kind: RecordKind::Struct,
            is_polymorphic: false,
            is_final: false,
            source_alignment: None,
        });
        let box_int_ty = c.intern_type(CxxType::Record(box_int));
        let box_float_ty = c.intern_type(CxxType::Record(box_float));
        (c, v, box_int_ty, box_float_ty, i)
    }

    // take_int_box(Box<int>)
    {
        let (mut c, v, box_int_ty, _, _) = make_ctx();
        let sig = FnSig {
            params: vec![box_int_ty],
            ret: v,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        };
        assert_eq!(
            c.mangle_msvc(&Symbol::Function {
                scope: NestedName(vec![]),
                name: Ident("take_int_box".into()),
                sig,
            }),
            "?take_int_box@@YAXU?$Box@H@@@Z"
        );
    }

    // take_two(Box<int>, Box<int>) — back-ref `0` on second.
    {
        let (mut c, v, box_int_ty, _, _) = make_ctx();
        let sig = FnSig {
            params: vec![box_int_ty, box_int_ty],
            ret: v,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        };
        assert_eq!(
            c.mangle_msvc(&Symbol::Function {
                scope: NestedName(vec![]),
                name: Ident("take_two".into()),
                sig,
            }),
            "?take_two@@YAXU?$Box@H@@0@Z"
        );
    }

    // take_int_and_float(Box<int>, Box<float>) — different types.
    {
        let (mut c, v, box_int_ty, box_float_ty, _) = make_ctx();
        let sig = FnSig {
            params: vec![box_int_ty, box_float_ty],
            ret: v,
            cv: CvQual::default(),
            ref_q: None,
            variadic: false,
            noexcept: false,
        };
        assert_eq!(
            c.mangle_msvc(&Symbol::Function {
                scope: NestedName(vec![]),
                name: Ident("take_int_and_float".into()),
                sig,
            }),
            "?take_int_and_float@@YAXU?$Box@H@@U?$Box@M@@@Z"
        );
    }
}

// -------- Itanium-vs-MSVC dispatcher round-trip -----------------------

#[test]
fn dispatcher_routes_on_abi_flavor() {
    // Same Symbol should mangle differently under the two flavors.
    let mut c_itanium = CxxTypeCtx::new(Target::x86_64_unknown_linux_gnu());
    let mut c_msvc = CxxTypeCtx::new(Target::x86_64_pc_windows_msvc());

    let i_itan = intern_int(&mut c_itanium, true, IntWidth::I32);
    let i_msvc = intern_int(&mut c_msvc, true, IntWidth::I32);
    let v_itan = intern_void(&mut c_itanium);
    let v_msvc = intern_void(&mut c_msvc);

    let sig_itan = FnSig {
        params: vec![i_itan],
        ret: v_itan,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };
    let sig_msvc = FnSig {
        params: vec![i_msvc],
        ret: v_msvc,
        cv: CvQual::default(),
        ref_q: None,
        variadic: false,
        noexcept: false,
    };

    let itan = c_itanium.mangle(&Symbol::Function {
        scope: NestedName(vec![]),
        name: Ident("foo".into()),
        sig: sig_itan,
    });
    let msvc = c_msvc.mangle(&Symbol::Function {
        scope: NestedName(vec![]),
        name: Ident("foo".into()),
        sig: sig_msvc,
    });
    // Itanium: `_Z3fooi` (with `v` as return). Actually wait — the
    // Itanium mangler doesn't encode the return type in free
    // functions. So `_Z3fooi`.
    assert_eq!(itan, "_Z3fooi");
    assert_eq!(msvc, "?foo@@YAXH@Z");

    // Round-trip through the explicit `_itanium` / `_msvc` entry
    // points returns the same strings.
    assert_eq!(
        itan,
        c_itanium.mangle_itanium(&Symbol::Function {
            scope: NestedName(vec![]),
            name: Ident("foo".into()),
            sig: FnSig {
                params: vec![i_itan],
                ret: v_itan,
                cv: CvQual::default(),
                ref_q: None,
                variadic: false,
                noexcept: false,
            },
        })
    );
}

